-- staff
WITH up AS (
  INSERT INTO staff (staff_id, name, role)
  SELECT staff_id, name, role FROM json_populate_recordset(NULL::staff, $1::json)
  ON CONFLICT (staff_id) DO UPDATE SET
    name = EXCLUDED.name,
    role = EXCLUDED.role
  RETURNING 1
)
SELECT count(*)::int AS upserted FROM up;

